def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    def evaluate(x):
        x = clip(x)
        return func(x)

    # Differential Evolution parameters
    pop_size = 50
    F = 1.0
    CR = 1.0

    # Simulated Annealing parameters
    T = 1000
    alpha = 0.95

    # Initialize population
    x = rng.uniform(lb, ub, (pop_size, dim))

    for t in range(budget):
        # Differential Evolution
        y = np.zeros((pop_size, dim))
        for i in range(pop_size):
            r1, r2, r3 = rng.randint(0, pop_size, 3)
            while r1 == i or r2 == i or r3 == i:
                r1, r2, r3 = rng.randint(0, pop_size, 3)
            y[i] = x[r1] + F * (x[r2] - x[r3])
        y = np.where(rng.uniform(size=(pop_size, dim)) < CR, y, x)

        # Simulated Annealing
        T *= alpha
        for i in range(pop_size):
            x_best = evaluate(x[i])
            y[i] = clip(y[i])
            y_new = evaluate(y[i])
            if rng.rand() < np.exp((x_best - y_new) / T):
                x[i] = y[i]

    return x[np.argmin([evaluate(x_i) for x_i in x])]

def algorithm(func, dim, lb, ub, budget, rng):
    def evaluate(x):
        return func(x)

    x_best = 0.5 * (ub + lb) + 0.1 * rng.uniform(-1, 1, size=dim)
    cov_mat = np.eye(dim) * 10
    for _ in range(budget):
        candidates = x_best + rng.normal(size=(10000, dim))
        for i in range(dim):
            candidates[:, i] *= (ub[i] - lb[i]) / np.std(candidates[:, i])
            candidates[:, i] += lb[i]
        candidates = np.clip(candidates, a_min=lb, a_max=ub)
        scores = evaluate(candidates)
        idx_best = np.argmax(scores)
        if scores[idx_best] < evaluate(x_best):
            x_best = candidates[idx_best]
        scores -= np.max(scores)
        cov_mat = 0.1 * (np.eye(dim) - np.dot(np.dot(cov_mat, candidates.T), candidates)) + \
                  0.9 * np.dot(np.dot(cov_mat, candidates.T), candidates)
    return x_best

